const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => '₹'+Number(n).toLocaleString('en-IN');
const seed={leads:[{id:101,name:'Priya Sharma',city:'Bangalore',area:'Whitefield',service:'Deep cleaning',property:'3 BHK · Furnished',amount:6499,status:'New enquiry',source:'Website',owner:'Ananya',phone:'Demo contact',note:'Moving in next week. Prefers a morning slot.'},{id:102,name:'Rahul Desai',city:'Bangalore',area:'Indiranagar',service:'Pest control',property:'2 BHK · Cockroaches',amount:2499,status:'Contacted',source:'WhatsApp',owner:'Ananya',phone:'Demo contact',note:'Call after 4 PM to confirm availability.'},{id:104,name:'Arjun Rao',city:'Hassan',area:'Vidyanagar',service:'Deep cleaning',property:'4 BHK · Empty villa',amount:8999,status:'New enquiry',source:'Phone',owner:'Kiran',phone:'Demo contact',note:'Needs a weekend appointment.'},{id:105,name:'Sneha Patel',city:'Bangalore',area:'HSR Layout',service:'Pest control',property:'3 BHK · Termites',amount:7999,status:'Quotation sent',source:'Website',owner:'Ananya',phone:'Demo contact',note:'Include a follow-up inspection.'},{id:106,name:'Vikram Shetty',city:'Bangalore',area:'JP Nagar',service:'Deep cleaning',property:'2 BHK · Furnished',amount:4999,status:'Contacted',source:'Referral',owner:'Ananya',phone:'Demo contact',note:'Kitchen needs extra attention.'}],jobs:[{id:2401,name:'Aditi Menon',city:'Bangalore',area:'Whitefield',service:'Deep cleaning',property:'3 BHK · Furnished',amount:6499,paid:2000,status:'In progress',team:'Team A · Ravi',date:'2026-09-13',time:'09:00',checks:[]},{id:2402,name:'Rohan Mehta',city:'Bangalore',area:'Koramangala',service:'Pest control',property:'2 BHK · General treatment',amount:2499,paid:2499,status:'Completed',team:'Team B · Suresh',date:'2026-09-13',time:'10:30',checks:[0,1,2]},{id:2404,name:'Nikhil Gowda',city:'Bangalore',area:'HSR Layout',service:'Deep cleaning',property:'2 BHK · Empty flat',amount:4999,paid:1500,status:'Scheduled',team:'Unassigned',date:'2026-09-13',time:'14:00',checks:[]},{id:2405,name:'Divya Hegde',city:'Hassan',area:'Kuvempu Nagar',service:'Pest control',property:'3 BHK · Termite inspection',amount:7999,paid:2000,status:'Scheduled',team:'Team D · Deepak',date:'2026-09-14',time:'09:00',checks:[]},{id:2406,name:'Sanjay Kumar',city:'Bangalore',area:'JP Nagar',service:'Deep cleaning',property:'4 BHK · Villa',amount:8999,paid:8999,status:'Completed',team:'Team A · Ravi',date:'2026-09-12',time:'09:00',checks:[0,1,2]}],tickets:[{id:301,name:'Sanjay Kumar',job:2406,issue:'Window cleaning touch-up requested',status:'Open',priority:'Medium'},{id:302,name:'Rohan Mehta',job:2402,issue:'Schedule post-treatment follow-up',status:'In progress',priority:'Low'}],activity:['Rohan Mehta’s pest control service completed','New enquiry from Priya Sharma · Website','Team A checked in at Whitefield']};
let db;try{db=JSON.parse(localStorage.getItem('vucare-demo-v1'))||structuredClone(seed)}catch{db=structuredClone(seed)}
// Keep existing browser data while removing discontinued service records.
const supportedServices = new Set(['Deep cleaning','Pest control']);
db.leads = db.leads.filter(record => supportedServices.has(record.service));
db.jobs = db.jobs.filter(record => supportedServices.has(record.service));
db.tickets = db.tickets.filter(ticket => db.jobs.some(job => job.id === ticket.job));
db.activity = db.activity.filter(entry => !/paint|Meera Nair|Lakshmi Iyer/i.test(entry));
try { localStorage.setItem('vucare-demo-v1', JSON.stringify(db)); } catch {}
let role='Admin',page='overview',query='',city='All cities';
const access={Admin:['assignments','overview','leads','visits','bookings','customers','schedule','payments','support','reports'],Manager:['assignments','overview','leads','visits','bookings','schedule'],Telecaller:['overview','leads'],'Site Inspector':['visits'],'Field Staff':['overview','schedule'],Accounts:['overview','payments','customers','reports'],Support:['overview','customers','bookings','support']};
const names={assignments:['⇄','Work assignment'],visits:['⌖','Site visits'],overview:['◫','Overview'],leads:['◷','Leads & follow-ups'],bookings:['▤','Bookings'],customers:['♧','Customers'],schedule:['▦','Team schedule'],payments:['▣','Payments'],support:['◉','Support & revisits'],reports:['▥','Reports']};
function save(message){try{localStorage.setItem('vucare-demo-v1',JSON.stringify(db))}catch{toast('Browser storage unavailable; changes last for this session.')}if(message){db.activity.unshift(message);db.activity=db.activity.slice(0,6);try{localStorage.setItem('vucare-demo-v1',JSON.stringify(db))}catch{}toast(message)}render()}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3200)}
function jobs(){return db.jobs.filter(j=>(!['Telecaller','Sales'].includes(role)||db.leads.some(l=>l.owner===currentPerson()&&(j.leadId===l.id||j.name===l.name)))&&(role!=='Field Staff'||(j.worker||j.team.split(' · ')[1])===currentPerson())&&(city==='All cities'||j.city===city))}
function leads(){return db.leads.filter(l=>(!['Sales','Telecaller'].includes(role)||l.owner===currentPerson()||(l.owner==='Unassigned'&&l.createdBy===currentPerson()))&&(city==='All cities'||l.city===city))}
function badge(s){const c=['Completed','Paid','Converted','Resolved'].includes(s)?'green':['New enquiry','Scheduled','Open','Unassigned'].includes(s)?'orange':['In progress','Contacted','Part paid'].includes(s)?'blue':s==='Quotation sent'?'purple':'';return `<span class="badge ${c}">${esc(s)}</span>`}
function initials(n){return n.split(' ').map(x=>x[0]).slice(0,2).join('')}
function person(j){return `<div class="customer-cell"><span class="avatar">${initials(j.name)}</span><div><strong>${esc(j.name)}</strong><small>${esc(j.area)}, ${esc(j.city)}</small></div></div>`}
function pageHeading(title,sub,action=''){return `<div class="page-top"><div><p class="eyebrow">VU CARE / ${role.toUpperCase()}</p><h1>${title}</h1><p class="sub">${sub}</p></div><div class="actions">${action}</div></div>`}
function stat(label,value,note,icon){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon}</span></div><strong>${value}</strong><small>${note}</small></div>`}
function citySelect(){return `<select id="city" aria-label="Filter by city">${['All cities','Bangalore','Mysore','Hassan'].map(x=>`<option ${x===city?'selected':''}>${x}</option>`).join('')}</select>`}
function go(p){if(!access[role].includes(p))return;page=p;query='';location.hash=p;render();document.body.classList.remove('nav-open')}
function render(){if(!access[role].includes(page))page=access[role][0];$('#nav').innerHTML=access[role].map(p=>`<a href="#${p}" class="${page===p?'active':''}" data-nav="${p}"><i>${names[p][0]}</i>${names[p][1]}</a>`).join('');$('#crumb').textContent=names[page][1];$('#profile-name').innerHTML=`${role==='Field Staff'?'Ravi · Team A':'Ananya Kumar'}<small>${esc(role)} · Demo view</small>`;$('#main').innerHTML=({assignments:assignmentPage,overview,leads:leadPage,visits:visitPage,bookings:bookingPage,customers:customerPage,schedule:schedulePage,payments:paymentPage,support:supportPage,reports:reportPage}[page])();}
function overview(){const js=jobs(),ls=leads(),total=js.reduce((s,j)=>s+j.paid,0),due=js.reduce((s,j)=>s+j.amount-j.paid,0);const today=js.filter(j=>j.date==='2026-09-13');let stats=role==='Field Staff'?stat('Assigned jobs',js.length,'Team A · Ravi','▦')+stat('Today’s visits',today.length,'13 September 2026','◷')+stat('In progress',js.filter(j=>j.status==='In progress').length,'Currently on site','◉')+stat('Completed',js.filter(j=>j.status==='Completed').length,'Ready for review','✓'):stat('Active enquiries',ls.filter(l=>l.status!=='Converted').length,'<b>'+ls.filter(l=>l.status==='New enquiry').length+' new</b> awaiting first contact','♧')+stat('Today’s jobs',today.length,`<b>${today.filter(j=>j.status==='Completed').length} completed</b> · ${today.filter(j=>j.status!=='Completed').length} remaining`,'▦')+stat('Payments collected',money(total),'Across the demo bookings','↗')+stat('Outstanding balance',money(due),`${js.filter(j=>j.paid<j.amount).length} bookings with balance due`,'▣');return pageHeading(role==='Field Staff'?'Your day, at a glance.':'Good morning, Ananya ☀','Here’s what’s happening at Vu Care today.',citySelect()+(['Admin','Manager','Sales','Telecaller'].includes(role)?'<button class="primary" data-action="new-lead">＋ New enquiry</button>':''))+`<div class="stats">${stats}</div>`+(role==='Field Staff'?jobCards(js):`<div class="grid"><section class="card"><div class="card-head"><div><h2>Booking value by service</h2><p>Sample bookings · September 2026</p></div><div class="legend"><span><em></em>Value</span><span><em class="light"></em>Collected</span></div></div><div class="chart-total"><strong>${money(js.reduce((s,j)=>s+j.amount,0))}</strong><span>${js.length} service bookings</span></div><div class="chart">${['Deep cleaning','Pest control'].map(s=>{let v=js.filter(j=>j.service===s).reduce((a,j)=>a+j.amount,0),p=js.filter(j=>j.service===s).reduce((a,j)=>a+j.paid,0);let max=Math.max(1,...['Deep cleaning','Pest control'].map(t=>js.filter(j=>j.service===t).reduce((a,j)=>a+j.amount,0)));return `<div class="bar-group" style="width:95px"><div class="bar" style="height:${v/max*95}%" title="${esc(s)}: ${money(v)}"></div><div class="bar light" style="height:${p/max*95}%" title="Collected: ${money(p)}"></div><small>${s}</small></div>`}).join('')}</div></section><section class="card"><div class="card-head"><div><h2>Service mix</h2><p>Where your teams are making a difference</p></div><span>◌</span></div>${['Deep cleaning','Pest control'].map((s,i)=>{const count=js.filter(j=>j.service===s).length;return `<div class="service-row"><div class="service-line"><span>${s}</span><b>${count} bookings</b></div><div class="track"><span style="width:${count/Math.max(js.length,1)*100}%;background:${['#2d7260','#a9c47d','#d5af6d'][i]}"></span></div></div>`}).join('')}<div class="service-note"><span>Across ${new Set(js.map(j=>j.city)).size} cities</span><strong>${js.length} total bookings</strong></div></section></div><div class="grid"><section class="card"><div class="card-head"><div><h2>Today’s service visits</h2><p>Sunday, 13 September</p></div><button class="text-button" data-nav="${access[role].includes('schedule')?'schedule':'bookings'}">View all →</button></div>${jobTable(today,true)}<div class="table-footer">${today.filter(j=>j.team==='Unassigned').length} booking needs a crew assignment</div></section><div><section class="card"><div class="card-head"><h2>Recent activity</h2><span class="badge">Demo</span></div><div class="activity">${db.activity.slice(0,3).map((a,i)=>`<div class="activity-item"><span class="activity-icon">${['✓','＋','↗'][i]}</span><div><p>${esc(a)}</p><small>${i===0?'Latest update':'Earlier in this demo'}</small></div></div>`).join('')}</div></section><div class="callout"><h3>${role==='Accounts'?'Keep collections on track':'A little follow-up goes a long way.'}</h3><p>${role==='Accounts'?`${money(due)} is awaiting collection.`:`${ls.filter(l=>l.status==='Quotation sent').length} quotations are waiting for a customer decision.`}</p><button data-nav="${access[role].includes('leads')?'leads':access[role].includes('payments')?'payments':'support'}">${access[role].includes('leads')?'Review follow-ups':'Open workspace'} →</button></div></div></div>`)}
function jobTable(list,compact=false){return `<div class="table-wrap"><table><thead><tr><th>CUSTOMER</th><th>SERVICE</th>${compact?'':'<th>DATE / TEAM</th>'}<th>STATUS</th><th></th></tr></thead><tbody>${list.map(j=>`<tr><td>${person(j)}</td><td>${esc(j.service)}<small>${compact?j.time:j.property}</small></td>${compact?'':`<td>${esc(j.date)} · ${esc(j.time)}<small>${esc(j.team)}</small></td>`}<td>${badge(j.status)}</td><td><button class="text-button" data-job="${j.id}" aria-label="Open booking ${j.id}">↗</button></td></tr>`).join('')}</tbody></table>${!list.length?'<div class="empty">No bookings match this view.</div>':''}</div>`}
function leadPage(){const list=leads().filter(l=>(l.name+' '+l.service+' '+l.area).toLowerCase().includes(query.toLowerCase()));return pageHeading('Every enquiry, an opportunity.','Track conversations and turn enquiries into booked services.','<button class="primary" data-action="new-lead">＋ New enquiry</button>')+`<div class="filters" style="padding:0 0 22px;border:0"><input class="search" id="search" placeholder="Search customer, service or area…" value="${esc(query)}" aria-label="Search leads">${citySelect()}</div><div class="board">${['New enquiry','Contacted','Quotation sent','Converted'].map(s=>`<section class="column"><h2>${s}<span>${list.filter(l=>l.status===s).length}</span></h2>${list.filter(l=>l.status===s).map(l=>`<article class="lead-card" tabindex="0" role="button" data-lead="${l.id}">${badge(l.service)}<h3 style="margin-top:13px">${esc(l.name)}</h3><p>${esc(l.property)}</p><p>${esc(l.area)} · ${esc(l.city)}</p><div class="lead-bottom"><b>${money(l.amount)}</b><span>${esc(l.source)}</span></div></article>`).join('')||'<p class="sub" style="padding:15px 5px">No enquiries in this stage</p>'}</section>`).join('')}</div>`}
function bookingPage(){return pageHeading('Bookings','One place for every service, visit and customer.',citySelect())+`<section class="card"><div class="filters"><input class="search" id="search" placeholder="Search bookings…" value="${esc(query)}" aria-label="Search bookings"></div>${jobTable(jobs().filter(j=>(j.name+' '+j.service+' '+j.status).toLowerCase().includes(query.toLowerCase())))}</section>`}
function customers(){const seen=new Map();[...jobs(),...(role==='Accounts'?[]:leads())].forEach(j=>{if(!seen.has(j.name))seen.set(j.name,j)});return [...seen.values()]}
function customerPage(){let list=customers().filter(c=>(c.name+' '+c.city).toLowerCase().includes(query.toLowerCase()));return pageHeading('Customers','A complete picture of every customer relationship.',citySelect())+`<section class="card"><div class="filters"><input class="search" id="search" value="${esc(query)}" placeholder="Search customers…" aria-label="Search customers"></div><div class="table-wrap"><table><thead><tr><th>CUSTOMER</th><th>PROPERTY</th><th>SERVICE</th><th>RELATIONSHIP</th><th></th></tr></thead><tbody>${list.map(c=>`<tr><td>${person(c)}</td><td>${esc(c.property)}</td><td>${esc(c.service)}</td><td>${badge(db.jobs.some(j=>j.name===c.name)?'Customer':'Enquiry')}</td><td><button class="text-button" data-customer="${esc(c.name)}">View history →</button></td></tr>`).join('')}</tbody></table>${list.length?'':'<div class="empty">No customers found.</div>'}</div></section>`}
function jobCards(list){return `<div class="schedule">${list.map(j=>`<article class="card job-card"><div class="service-line"><b>${esc(j.time)} · ${esc(j.date.slice(5))}</b>${badge(j.status)}</div><h3>${esc(j.name)}</h3><p>${esc(j.service)} · ${esc(j.property)}</p><p>⌖ ${esc(j.area)}, ${esc(j.city)}</p><div class="service-note" style="padding:15px 0 0"><span>${esc(j.team)} · Worker: ${esc(j.worker||'Unassigned')}</span><b>#VC-${j.id}</b></div><div class="actions"><button data-job="${j.id}" class="${role==='Field Staff'?'primary':''}">${role==='Field Staff'?'Open job checklist':'Manage booking'} →</button></div></article>`).join('')||'<div class="empty">No jobs assigned.</div>'}</div>`}
function schedulePage(){return pageHeading(role==='Field Staff'?'My service visits':'Team schedule',role==='Field Staff'?'Your assigned jobs, checklists and completion updates.':'Manage upcoming visits and keep every crew on track.',citySelect())+jobCards(jobs().slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)))}
function paymentPage(){const js=jobs();return pageHeading('Payments','Track advances, collections and outstanding balances.',citySelect())+`<div class="stats">${stat('Booking value',money(js.reduce((s,j)=>s+j.amount,0)),'All sample bookings','▤')}${stat('Collected',money(js.reduce((s,j)=>s+j.paid,0)),'Recorded payments','✓')}${stat('Outstanding',money(js.reduce((s,j)=>s+j.amount-j.paid,0)),'Balance to collect','◷')}${stat('Fully paid',js.filter(j=>j.amount===j.paid).length,'Bookings settled','▣')}</div><section class="card"><div class="card-head"><h2>Invoices & collections</h2></div><div class="table-wrap"><table><thead><tr><th>CUSTOMER / INVOICE</th><th>TOTAL</th><th>PAID</th><th>BALANCE</th><th>STATUS</th><th></th></tr></thead><tbody>${js.map(j=>`<tr><td><strong>${esc(j.name)}</strong><small>INV-${j.id}</small></td><td>${money(j.amount)}</td><td>${money(j.paid)}</td><td>${money(j.amount-j.paid)}</td><td>${badge(j.paid===j.amount?'Paid':j.paid?'Part paid':'Unpaid')}</td><td><button class="text-button" data-invoice="${j.id}">${j.paid<j.amount?'Record payment':'View invoice'} →</button></td></tr>`).join('')}</tbody></table></div></section>`}
function supportPage(){return pageHeading('Support & revisits','Close the loop on customer feedback and follow-up visits.','<button class="primary" data-action="new-ticket">＋ New request</button>')+`<section class="card"><div class="table-wrap"><table><thead><tr><th>CUSTOMER</th><th>REQUEST</th><th>PRIORITY</th><th>STATUS</th><th></th></tr></thead><tbody>${db.tickets.map(t=>`<tr><td><strong>${esc(t.name)}</strong><small>Booking #VC-${t.job}</small></td><td>${esc(t.issue)}</td><td>${badge(t.priority)}</td><td>${badge(t.status)}</td><td>${t.status==='Resolved'?'✓':`<button class="text-button" data-ticket="${t.id}">${t.status==='Open'?'Start review':'Resolve'} →</button>`}</td></tr>`).join('')}</tbody></table></div></section>`}
function reportPage(){const js=jobs();return pageHeading('Business reports','A clear view of service performance across your cities.','<button data-action="export">↓ Export bookings CSV</button>')+`<div class="report-grid">${[['Revenue by city',['Bangalore','Mysore','Hassan'],'city'],['Revenue by service',['Deep cleaning','Pest control'],'service']].map(([t,vals,key])=>`<section class="card"><div class="card-head"><h2>${t}</h2></div>${vals.map(v=>`<div class="metric-row"><span>${v}</span><b>${money(js.filter(j=>j[key]===v).reduce((s,j)=>s+j.amount,0))}</b></div>`).join('')}</section>`).join('')}<section class="card"><div class="card-head"><h2>Job performance</h2></div>${['Scheduled','In progress','Completed'].map(s=>`<div class="metric-row">${badge(s)}<b>${js.filter(j=>j.status===s).length} bookings</b></div>`).join('')}</section><section class="card"><div class="card-head"><h2>Collections summary</h2></div><div class="metric-row"><span>Collected</span><b>${money(js.reduce((s,j)=>s+j.paid,0))}</b></div><div class="metric-row"><span>Outstanding</span><b>${money(js.reduce((s,j)=>s+j.amount-j.paid,0))}</b></div><div class="metric-row"><span>Collection rate</span><b>${Math.round(js.reduce((s,j)=>s+j.paid,0)/Math.max(1,js.reduce((s,j)=>s+j.amount,0))*100)}%</b></div></section></div>`}
function modal(title,body,footer=''){const d=$('#dialog');$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button data-action="close" aria-label="Close dialog">✕</button></div>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}`;d.showModal()}
function options(a,v){return a.map(x=>`<option ${x===v?'selected':''}>${esc(x)}</option>`).join('')}
function newLead(){modal('New customer enquiry',`<form id="lead-form"><div class="modal-body form-grid"><label>Customer name<input name="name" required maxlength="70" placeholder="Full name"></label><label>Phone<input name="phone" required maxlength="30" placeholder="Contact number"></label><label>Service<select name="service">${options(['Deep cleaning','Pest control'])}</select></label><label>City<select name="city">${options(['Bangalore','Mysore','Hassan'])}</select></label><label>Area<input name="area" required placeholder="e.g. Whitefield" maxlength="70"></label><label>Property details<input name="property" required placeholder="e.g. 3 BHK, furnished" maxlength="100"></label><label>Estimated value (₹)<input name="amount" type="number" min="1" max="10000000" step="1" required value="6499"></label><label>Lead source<select name="source">${options(['Telecaller','Website','WhatsApp','Phone','Referral','Other'],role==='Telecaller'?'Telecaller':'Website')}</select></label><label class="full">Notes<textarea name="note" rows="2" maxlength="500"></textarea></label></div><div class="modal-footer"><button type="button" data-action="close">Cancel</button><button class="primary">Create enquiry</button></div></form>`)}
function leadDetail(id){let l=leads().find(l=>l.id===id);if(!l)return;modal(esc(l.name),`<div class="modal-body"><div class="detail-list"><div><small>Service</small>${esc(l.service)}</div><div><small>Estimated value</small>${money(l.amount)}</div><div><small>Property</small>${esc(l.property)}</div><div><small>Location</small>${esc(l.area)}, ${esc(l.city)}</div><div><small>Source</small>${esc(l.source)}</div><div><small>Contact</small>${esc(l.phone)}</div></div><p>${esc(l.note)}</p><label class="sub">Lead stage <select id="lead-stage">${options(['New enquiry','Contacted','Quotation sent'],l.status)}</select></label></div>`,l.status==='Converted'?'<button data-action="close">Close</button>':`<button data-save-lead="${id}">Save stage</button><button class="primary" data-convert="${id}">Convert to booking →</button>`)}
function jobDetail(id){let j=jobs().find(j=>j.id===id);if(!j)return;const canManage=canAssign(),field=role==='Field Staff';modal(`Booking #VC-${j.id}`,`<div class="modal-body"><h3>${esc(j.name)}</h3><p>${esc(j.service)} · ${esc(j.property)}<br>${esc(j.area)}, ${esc(j.city)}</p><div class="detail-list"><div><small>Visit</small>${esc(j.date)} · ${esc(j.time)}</div><div><small>Status</small>${badge(j.status)}</div><div><small>Assigned crew</small>${esc(j.team)}</div>${field?'':`<div><small>Booking value</small>${money(j.amount)}</div>`}</div>${canManage?`<div class="form-grid" style="margin-top:24px"><label>Crew<select id="job-team">${options(['Unassigned','Team A · Ravi','Team B · Suresh','Team C · Mahesh','Team D · Deepak'],j.team)}</select></label><label>Date<input type="date" id="job-date" value="${esc(j.date)}" required></label><label>Time<input type="time" id="job-time" value="${esc(j.time)}" required></label><label>Status<select id="job-status">${options(['Scheduled','In progress','Completed'],j.status)}</select></label></div>`:''}${field?`<div class="checklist">${['Site preparation confirmed','Service checklist completed','Customer completion confirmation'].map((s,i)=>`<label><input type="checkbox" data-check="${i}" ${j.checks.includes(i)?'checked':''}>${s}</label>`).join('')}</div><p class="sub">Completion requires all three checks.</p>`:''}</div>`,canManage?`<button class="primary" data-save-job="${id}">Save booking</button>`:field?`<button data-field-save="${id}">Save checklist</button><button class="primary" data-field-next="${id}" ${j.status==='Completed'?'disabled':''}>${j.status==='Scheduled'?'Start job':j.status==='Completed'?'Completed':'Complete job'}</button>`:'<button data-action="close">Close</button>')}
function invoice(id){let j=jobs().find(j=>j.id===id);if(!j)return;modal(`Invoice INV-${id}`,`<div class="modal-body"><p class="eyebrow">VU CARE SERVICES · DEMO INVOICE</p><h3>${esc(j.name)}</h3><p>${esc(j.service)} · ${esc(j.property)}<br>${esc(j.area)}, ${esc(j.city)}</p><div class="metric-row"><span>Service amount</span><b>${money(j.amount)}</b></div><div class="metric-row"><span>Paid</span><b>${money(j.paid)}</b></div><div class="metric-row"><span>Balance due</span><b>${money(j.amount-j.paid)}</b></div>${j.paid<j.amount?`<form id="pay-form" data-id="${id}"><div class="form-grid" style="margin-top:20px"><label>Payment amount (₹)<input name="amount" type="number" required min="1" max="${j.amount-j.paid}" value="${j.amount-j.paid}"></label><label>Method<select name="method">${options(['UPI','Bank transfer','Cash','Card'])}</select></label></div><p class="sub" style="margin:15px 0">Demo entry only. No money is charged.</p><button class="primary">Record payment</button></form>`:''}</div>`,'<button data-action="print">Print invoice</button>')}
function customerDetail(name){let c=customers().find(c=>c.name===name);if(!c)return;const history=db.jobs.filter(j=>j.name===name);modal(esc(c.name),`<div class="modal-body"><p>${esc(c.area)}, ${esc(c.city)}<br>${esc(c.property)}</p><h3>Service history</h3>${history.length?history.map(j=>`<div class="metric-row"><span>${esc(j.service)}<small style="display:block">${esc(j.date)}</small></span>${badge(j.status)}</div>`).join(''):'<p class="sub" style="margin-top:15px">Prospective customer · No completed bookings yet.</p>'}</div>`,'<button data-action="close">Close</button>')}
function ticketForm(){modal('New support request',`<form id="ticket-form"><div class="modal-body form-grid"><label class="full">Booking<select name="job">${db.jobs.map(j=>`<option value="${j.id}">VC-${j.id} · ${esc(j.name)}</option>`).join('')}</select></label><label class="full">Request<textarea name="issue" required maxlength="300" rows="3"></textarea></label><label>Priority<select name="priority">${options(['Low','Medium','High'])}</select></label></div><div class="modal-footer"><button class="primary">Create request</button></div></form>`)}
function exportCSV(){const rows=[['Booking','Customer','City','Service','Date','Status','Amount','Paid'],...jobs().map(j=>[j.id,j.name,j.city,j.service,j.date,j.status,j.amount,j.paid])];const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const u=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='vu-care-demo-bookings.csv';a.click();URL.revokeObjectURL(u);toast('Booking report exported')}
document.addEventListener('click',e=>{const el=e.target.closest('button,a,[data-lead]');if(!el)return;const d=el.dataset;if(d.nav){e.preventDefault();go(d.nav)}if(d.action==='close')$('#dialog').close();if(d.action==='new-lead')newLead();if(d.action==='new-ticket')ticketForm();if(d.action==='print')window.print();if(d.action==='export')exportCSV();if(d.lead)leadDetail(+d.lead);if(d.job)jobDetail(+d.job);if(d.invoice)invoice(+d.invoice);if(d.customer)customerDetail(d.customer);if(d.saveLead){if(!saveLeadWorkflow(+d.saveLead))return;$('#dialog').close();save('Lead follow-up and site visit saved')}if(d.convert){if(!canAssign())return toast('Only a manager can confirm and assign work');const l=leads().find(l=>l.id===+d.convert);if(!l||l.status==='Converted')return;if(l.visitStatus==='Scheduled')return toast('Complete the site visit before assigning this job');l.status='Converted';db.jobs.push({...l,id:Math.max(...db.jobs.map(j=>j.id))+1,paid:0,status:'Scheduled',team:'Unassigned',date:'2026-09-14',time:'09:00',checks:[]});$('#dialog').close();save(`${l.name} converted to a booking`);go('bookings')}if(d.saveJob){if(!canAssign())return toast('Only a manager can assign work');const j=jobs().find(j=>j.id===+d.saveJob);if(!$('#job-date').value||!$('#job-time').value)return toast('Choose a visit date and time');const previousWorker=j.worker;Object.assign(j,{team:$('#job-team').value,date:$('#job-date').value,time:$('#job-time').value,status:$('#job-status').value,worker:$('#job-worker').value,location:$('#job-location').value});if(j.worker!==previousWorker)logAssignment(j,'Worker',previousWorker,j.worker);$('#dialog').close();save('Booking and crew assignment updated')}if(d.fieldSave||d.fieldNext){const j=jobs().find(j=>j.id===+(d.fieldSave||d.fieldNext));j.location=$('#field-location').value.trim();j.workNote=$('#work-note').value.trim();j.checks=[...document.querySelectorAll('[data-check]:checked')].map(c=>+c.dataset.check);if(d.fieldNext){if(j.status==='Scheduled')j.status='In progress';else if(j.checks.length===3)j.status='Completed';else return toast('Complete all three checks before closing this job')}$('#dialog').close();save('Job progress saved')}if(d.ticket){const t=db.tickets.find(t=>t.id===+d.ticket);t.status=t.status==='Open'?'In progress':'Resolved';save('Support request updated')}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,values=Object.fromEntries(new FormData(f));if(f.id==='lead-form'){if(!values.name.trim()||!values.area.trim())return toast('Enter a customer name and area');db.leads.unshift({...values,name:values.name.trim(),amount:Number(values.amount),id:Date.now(),status:'New enquiry',owner:'Unassigned',createdBy:currentPerson(),assignmentHistory:[]});$('#dialog').close();page='leads';save(`${values.name} added as a new enquiry`)}if(f.id==='pay-form'){const j=jobs().find(j=>j.id===+f.dataset.id),n=Number(values.amount);if(!Number.isFinite(n)||n<=0||n>j.amount-j.paid)return toast('Enter an amount within the outstanding balance');j.paid+=n;$('#dialog').close();save(`${money(n)} payment recorded for ${j.name}`)}if(f.id==='ticket-form'){const j=db.jobs.find(j=>j.id===+values.job);if(!values.issue.trim())return;db.tickets.unshift({id:Date.now(),name:j.name,job:j.id,issue:values.issue,priority:values.priority,status:'Open'});$('#dialog').close();save('Support request created')}});
document.addEventListener('change',e=>{if(e.target.id==='role'){role=e.target.value;city='All cities';query='';$('#dialog').close();render()}if(e.target.id==='city'){city=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const p=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(p,p)}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-lead]')){e.preventDefault();leadDetail(+e.target.dataset.lead)}});
$('#menu').onclick=()=>document.body.classList.toggle('nav-open');$('#reset').onclick=()=>modal('Reset the demo?',`<div class="modal-body"><p>This restores the original fictional records and removes your changes in this browser.</p></div>`,'<button data-action="close">Cancel</button><button class="primary" id="confirm-reset">Reset demo</button>');document.addEventListener('click',e=>{if(e.target.id==='confirm-reset'){db=structuredClone(seed);normalizeWorkflow();$('#dialog').close();save('Demo data restored')}});
let leadLayout='sheet';
const workers=['Unassigned','Ravi','Suresh','Mahesh','Deepak'];
function normalizeWorkflow(){
 for(const l of db.leads){l.assignmentHistory??=[];l.owner??='Unassigned';l.followups??=[];l.nextFollowup??=(l.id===102?'2026-09-14T10:00':'');l.visitStatus??=(l.id===102?'Scheduled':'Not required');l.visitOwner??='Ravi';l.visitDate??=(l.id===102?'2026-09-14':'');l.visitTime??='09:00';l.visitNotes??='';}
 for(const j of db.jobs){j.assignmentHistory??=[];j.worker??=(j.team.includes(' · ')?j.team.split(' · ')[1]:'Unassigned');j.location??=j.area+', '+j.city;j.photos??=[];j.workNote??='';}
}
normalizeWorkflow();
function mapLink(location){return `<a class="text-button" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(location)}">Open location ↗</a>`}
function filteredLeadList(){return leads().filter(l=>(l.name+' '+l.service+' '+l.area+' '+l.phone).toLowerCase().includes(query.toLowerCase()))}
leadPage=function(){const list=filteredLeadList();return pageHeading('Leads & follow-ups','Capture the enquiry, follow up, arrange a site visit and hand over the job.','<button class="primary" data-action="new-lead">＋ New enquiry</button>')+`<div class="workflow-strip"><span>01 · Telecaller enquiry</span><span>02 · Follow-up</span><span>03 · Site visit</span><span>04 · Job assignment</span></div><div class="filters" style="padding:0 0 22px;border:0"><input class="search" id="search" placeholder="Search customer, phone or area…" value="${esc(query)}" aria-label="Search leads">${citySelect()}<button data-layout="sheet" aria-pressed="${leadLayout==='sheet'}">▤ Lead sheet</button><button data-layout="board" aria-pressed="${leadLayout==='board'}">◫ Pipeline</button><button data-export-leads>↓ Export CSV</button></div>`+(leadLayout==='board'?`<div class="board">${['New enquiry','Contacted','Quotation sent','Converted'].map(s=>`<section class="column"><h2>${s}<span>${list.filter(l=>l.status===s).length}</span></h2>${list.filter(l=>l.status===s).map(l=>`<article class="lead-card" tabindex="0" role="button" data-lead="${l.id}">${badge(l.service)}<h3 style="margin-top:13px">${esc(l.name)}</h3><p>${esc(l.area)} · ${esc(l.city)}</p><p>Next follow-up: ${esc(l.nextFollowup?.replace('T',' ')||'Not set')}</p><div class="lead-bottom"><b>${money(l.amount)}</b>${badge(l.visitStatus==='Not required'?'No inspection':l.visitStatus)}</div></article>`).join('')||'<p class="sub">No enquiries</p>'}</section>`).join('')}</div>`:`<section class="card"><div class="table-wrap"><table><thead><tr><th>CUSTOMER / PHONE</th><th>SERVICE / VALUE</th><th>SOURCE / TELECALLER</th><th>NEXT FOLLOW-UP</th><th>SITE VISIT</th><th>LEAD STATUS</th><th></th></tr></thead><tbody>${list.map(l=>`<tr><td>${person(l)}<small>${esc(l.phone)}</small></td><td>${esc(l.service)}<small>${money(l.amount)}</small></td><td>${esc(l.source)}<small>${esc(l.owner)}</small></td><td>${esc(l.nextFollowup?.replace('T',' ')||'Not set')}<small>${l.followups?.length||0} follow-up notes</small></td><td>${badge(l.visitStatus||'Not required')}<small>${esc(l.visitDate||'')}</small></td><td>${badge(l.status)}</td><td><button class="text-button" data-lead="${l.id}">Manage →</button></td></tr>`).join('')}</tbody></table>${list.length?'':'<div class="empty">No matching enquiries.</div>'}</div></section>`)};
function leadFormFields(l){return `<label>Lead stage<select id="lead-stage">${options(['New enquiry','Contacted','Quotation sent'],l.status)}</select></label><label>Telecaller / lead owner<select id="lead-owner" ${!canAssign()?'disabled':''}>${options(['Unassigned','Ananya','Kiran'],l.owner)}</select></label><label>Next follow-up<input type="datetime-local" id="lead-followup" value="${esc(l.nextFollowup||'')}"></label><label>Estimated value (₹)<input type="number" min="1" max="10000000" id="lead-value" value="${l.amount}"></label><label class="full">Call / follow-up note<textarea id="followup-note" maxlength="500" rows="2" placeholder="Add what the customer said and the next action"></textarea></label><label>Site visit<select id="visit-status" ${!canAssign()?'disabled':''}>${options(['Not required','Scheduled','Completed'],l.visitStatus)}</select></label><label>Site inspector<select id="visit-owner" ${!canAssign()?'disabled':''}>${options(['Ravi','Mahesh','Deepak'],l.visitOwner)}</select></label><label>Visit date<input type="date" id="visit-date" ${!canAssign()?'disabled':''} value="${esc(l.visitDate||'')}"></label><label>Visit time<input type="time" id="visit-time" ${!canAssign()?'disabled':''} value="${esc(l.visitTime||'09:00')}"></label><label class="full">Inspection findings<textarea id="visit-notes" ${!canAssign()?'readonly':''} maxlength="1000" rows="2" placeholder="Property condition, scope of work and customer requirements">${esc(l.visitNotes||'')}</textarea></label>`}
leadDetail=function(id){const l=leads().find(l=>l.id===id);if(!l)return;modal(esc(l.name),`<div class="modal-body"><p>${esc(l.service)} · ${esc(l.property)}<br>${esc(l.area)}, ${esc(l.city)} · ${esc(l.phone)}</p><p class="sub">${esc(l.note)}</p>${l.status==='Converted'?`<p>${badge('Converted')} · Handed over for job assignment.</p>`:`<div class="form-grid" style="margin-top:20px">${leadFormFields(l)}</div>`}<h3 style="margin:24px 0 10px">Follow-up history</h3>${(l.followups||[]).slice().reverse().map(f=>`<div class="activity-item"><div><p>${esc(f.note)}</p><small>${esc(f.by)} · ${esc(f.at)}</small></div></div>`).join('')||'<p class="sub">No follow-ups logged yet.</p>'}</div>`,l.status==='Converted'?'<button data-action="close">Close</button>':`<button data-save-lead="${id}">Save follow-up / visit</button>${canAssign()?`<button class="primary" data-handover="${id}">Confirm & create job →</button>`:''}`)};
function saveLeadWorkflow(id){const l=leads().find(l=>l.id===id);if(!l)return false;if(!canAssign()){if(!['Sales','Telecaller'].includes(role)||l.owner!==currentPerson()){toast('This lead is awaiting manager assignment');return false}l.status=$('#lead-stage').value;l.nextFollowup=$('#lead-followup').value;const note=$('#followup-note').value.trim();if(note)l.followups.push({note,by:currentPerson(),at:new Date().toLocaleString('en-IN')});return true}const previousOwner=l.owner,previousInspector=l.visitOwner;const status=$('#visit-status').value,date=$('#visit-date').value,time=$('#visit-time').value,notes=$('#visit-notes').value.trim(),amount=Number($('#lead-value').value);if(!Number.isFinite(amount)||amount<=0||amount>10000000){toast('Enter a valid estimated value');return false}if(status!=='Not required'&&(!date||!time)){toast('Choose a site visit date and time');return false}if(status==='Completed'&&!notes){toast('Add inspection findings before completing the visit');return false}Object.assign(l,{status:$('#lead-stage').value,owner:$('#lead-owner').value,nextFollowup:$('#lead-followup').value,amount,visitStatus:status,visitOwner:$('#visit-owner').value,visitDate:date,visitTime:time,visitNotes:notes});if(l.owner!==previousOwner)logAssignment(l,'Lead',previousOwner,l.owner);if(l.visitOwner!==previousInspector)logAssignment(l,'Inspector',previousInspector,l.visitOwner);const note=$('#followup-note').value.trim();if(note)l.followups.push({note,by:role,at:new Date().toLocaleString('en-IN')});return true}
function visitPage(){const list=leads().filter(l=>l.visitStatus!=='Not required'&&(role!=='Site Inspector'||l.visitOwner===currentPerson()));return pageHeading('Site visits',role==='Site Inspector'?'Ravi’s assigned inspections. Record findings before the job is confirmed.':'Assign inspections and review the findings before handing over work.',citySelect())+`<div class="schedule">${list.map(l=>`<article class="card job-card"><div class="service-line"><b>${esc(l.visitDate)} · ${esc(l.visitTime)}</b>${badge(l.visitStatus)}</div><h3>${esc(l.name)}</h3><p>${esc(l.service)} · ${esc(l.property)}</p><p>⌖ ${esc(l.area)}, ${esc(l.city)}</p>${mapLink(l.area+', '+l.city)}<div class="service-note"><span>Inspector: ${esc(l.visitOwner)}</span><span>Lead #${l.id}</span></div><div class="actions"><button data-inspect="${l.id}" class="primary">${l.visitStatus==='Completed'?'View findings':'Open inspection'} →</button></div></article>`).join('')||'<section class="card empty">No site visits scheduled. Arrange one from a lead’s details.</section>'}</div>`}
function inspectionDetail(id){const l=leads().find(l=>l.id===id);if(!l||(role==='Site Inspector'&&l.visitOwner!==currentPerson()))return;modal(`Site inspection · ${esc(l.name)}`,`<form id="inspection-form" data-id="${id}"><div class="modal-body"><p>${esc(l.service)} · ${esc(l.property)}<br>${esc(l.area)}, ${esc(l.city)}</p><div class="form-grid"><label>Visit date<input name="date" type="date" value="${esc(l.visitDate)}" required></label><label>Time<input name="time" type="time" value="${esc(l.visitTime)}" required></label><label class="full">Inspection findings<textarea name="notes" rows="4" required maxlength="1000">${esc(l.visitNotes)}</textarea></label></div></div><div class="modal-footer"><button class="primary">Save & complete inspection</button></div></form>`)}
const oldJobDetail=jobDetail;
jobDetail=function(id){oldJobDetail(id);const j=jobs().find(j=>j.id===id);if(!j)return;const body=$('#modal-content .modal-body');if(!body)return;const manager=canAssign(),field=role==='Field Staff';if(manager){body.insertAdjacentHTML('beforeend',`<div class="form-grid" style="margin-top:18px"><label>Assigned worker<select id="job-worker">${options(workers,j.worker||'Unassigned')}</select></label><label>Job location / address<input id="job-location" maxlength="200" value="${esc(j.location||j.area+', '+j.city)}"></label></div>`)}if(field){body.insertAdjacentHTML('beforeend',`<div class="form-grid" style="margin-top:18px"><label class="full">Job location / address<input id="field-location" maxlength="200" value="${esc(j.location||j.area+', '+j.city)}"></label><label class="full">Work notes<textarea id="work-note" maxlength="1000" rows="2">${esc(j.workNote||'')}</textarea></label></div>`)}body.insertAdjacentHTML('beforeend',`<div class="evidence"><h3>Job location & work photos</h3><p>${esc(j.location||j.area+', '+j.city)} · Worker: ${esc(j.worker||'Unassigned')}</p>${mapLink(j.location||j.area+', '+j.city)}${j.workNote?`<p>${esc(j.workNote)}</p>`:''}<div class="photo-grid">${(j.photos||[]).map((p,i)=>`<figure><img src="${esc(p.url)}" alt="${esc(p.kind)} work photo ${i+1}"><figcaption>${esc(p.kind)} · ${esc(p.name)}</figcaption></figure>`).join('')||'<p class="sub">No work photos added yet.</p>'}</div>${manager||field?`<div class="form-grid"><label>Photo category<select id="photo-kind">${options(['Before work','After work','Site condition'])}</select></label><label>Add photo<input type="file" id="job-photo" data-job-id="${id}" accept="image/jpeg,image/png,image/webp"></label></div><p class="sub" style="margin-top:12px">Demo photos stay in this browser. Use sample photos; up to 4 per job, 5 MB per file.</p>`:''}</div>`)};
function downloadLeadCSV(){const rows=[['Lead','Customer','Phone','Service','Area','City','Telecaller','Status','Next follow-up','Visit status','Inspector','Visit date','Value'],...filteredLeadList().map(l=>[l.id,l.name,l.phone,l.service,l.area,l.city,l.owner,l.status,l.nextFollowup,l.visitStatus,l.visitOwner,l.visitDate,l.amount])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"''$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const u=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='vu-care-lead-sheet.csv';a.click();URL.revokeObjectURL(u);toast('Lead sheet exported')}
function persistPhoto(job,photo){const previous=job.photos;job.photos=[...previous,photo];try{localStorage.setItem('vucare-demo-v1',JSON.stringify(db));return true}catch{job.photos=previous;toast('Browser storage is full. Photo was not saved.');return false}}
async function addJobPhoto(input){const j=jobs().find(j=>j.id===+input.dataset.jobId),file=input.files?.[0];if(!j||!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){input.value='';return toast('Choose a JPG, PNG or WebP image under 5 MB')}if(j.photos.length>=4){input.value='';return toast('The demo allows up to 4 photos per job')}const kind=$('#photo-kind').value,uploadRole=role;input.disabled=true;try{const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas'),scale=Math.min(1,800/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const photo={url:canvas.toDataURL('image/jpeg',0.65),kind,name:file.name,at:new Date().toISOString()};if(persistPhoto(j,photo)){toast('Work photo saved in this browser');if(role===uploadRole&&$('#dialog').open){const gallery=$('#modal-content .photo-grid');if(gallery)gallery.innerHTML=j.photos.map((p,i)=>`<figure><img src="${esc(p.url)}" alt="${esc(p.kind)} work photo ${i+1}"><figcaption>${esc(p.kind)} · ${esc(p.name)}</figcaption></figure>`).join('')}}}catch{toast('This image could not be opened. Try another photo.')}finally{input.disabled=false;input.value=''}}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;const d=el.dataset;if(d.layout){leadLayout=d.layout;render()}if('exportLeads' in d)downloadLeadCSV();if(d.inspect)inspectionDetail(+d.inspect);if(d.handover){if(!canAssign())return toast('Only a manager can confirm and assign work');if(!saveLeadWorkflow(+d.handover))return;const l=leads().find(l=>l.id===+d.handover);if(l.visitStatus==='Scheduled')return toast('Complete the scheduled site visit before confirming the job');if(l.status==='Converted')return;l.status='Converted';db.jobs.push({...l,id:Math.max(2400,...db.jobs.map(j=>j.id))+1,leadId:l.id,paid:0,status:'Scheduled',team:'Unassigned',worker:'Unassigned',date:l.visitDate||'2026-09-14',time:'09:00',location:l.area+', '+l.city,photos:[],workNote:'',checks:[]});$('#dialog').close();save(`${l.name} confirmed; job ready for assignment`);if(access[role].includes('bookings'))go('bookings')}});
document.addEventListener('submit',e=>{if(e.target.id!=='inspection-form')return;e.preventDefault();const l=leads().find(l=>l.id===+e.target.dataset.id);if(!l||(role==='Site Inspector'&&l.visitOwner!==currentPerson()))return;const v=Object.fromEntries(new FormData(e.target));if(!v.notes.trim()||!v.date||!v.time)return;Object.assign(l,{visitNotes:v.notes.trim(),visitDate:v.date,visitTime:v.time,visitStatus:'Completed'});$('#dialog').close();save(`Site inspection completed for ${l.name}`)});
document.addEventListener('change',e=>{if(e.target.id==='job-photo')addJobPhoto(e.target)});
const baseRender=render;render=function(){normalizeWorkflow();baseRender();if(role==='Telecaller'){$('#profile-name').innerHTML='Ananya · Telecaller<small>Assigned enquiries & follow-ups</small>'}if(role==='Site Inspector'){$('#profile-name').innerHTML='Ravi · Site inspector<small>Assigned inspections</small>'}};

let assignmentSource='All sources',onlyUnassigned=false;
const demoPeople={Telecaller:['Ananya','Kiran'],Sales:['Ananya','Kiran'],'Site Inspector':['Ravi','Mahesh','Deepak'],'Field Staff':['Ravi','Suresh','Mahesh','Deepak']};
const selectedPeople={};
function currentPerson(){return selectedPeople[role]||demoPeople[role]?.[0]||(role==='Manager'?'Manager':'Ananya')}
function canAssign(){return ['Admin','Manager'].includes(role)}
function logAssignment(record,type,from,to){record.assignmentHistory??=[];record.assignmentHistory.push({type,from:from||'Unassigned',to,by:role,at:new Date().toLocaleString('en-IN')})}
function assignmentPage(){if(!canAssign())return '<div class="empty">Manager access required.</div>';const ls=leads().filter(l=>l.status!=='Converted'&&(assignmentSource==='All sources'||l.source===assignmentSource)&&(!onlyUnassigned||l.owner==='Unassigned'));const js=jobs().filter(j=>j.status!=='Completed'&&(!onlyUnassigned||j.worker==='Unassigned'));return pageHeading('Manage teams and assignments.','Assign leads to telecallers, schedule site inspections, and allocate confirmed jobs to field workers.','<button class="primary" data-action="new-lead">＋ Add incoming lead</button>')+`<div class="stats">${stat('Awaiting telecaller',leads().filter(l=>l.owner==='Unassigned'&&l.status!=='Converted').length,'Leads from every source','♧')}${stat('Scheduled inspections',leads().filter(l=>l.visitStatus==='Scheduled').length,'Manage inspector workload','⌖')}${stat('Jobs without a worker',jobs().filter(j=>j.worker==='Unassigned'&&j.status!=='Completed').length,'Ready for allocation','⇄')}${stat('Active work',jobs().filter(j=>j.status==='In progress').length,'Field work in progress','◷')}</div><div class="workflow-strip"><span>Lead from any source</span><span>Manager assigns telecaller</span><span>Manager assigns inspector</span><span>Manager assigns job</span></div><section class="card"><div class="card-head"><div><h2>Telecaller and site-inspector management</h2><p>Lead source shows where the enquiry came from. The manager controls follow-up and inspection ownership.</p></div></div><div class="filters"><select id="assignment-source" aria-label="Lead source filter">${options(['All sources','Telecaller','Website','WhatsApp','Phone','Referral','Other'],assignmentSource)}</select><label class="queue-toggle"><input id="unassigned-only" type="checkbox" ${onlyUnassigned?'checked':''}> Show only unassigned work</label>${citySelect()}</div><div class="table-wrap"><table><thead><tr><th>CUSTOMER</th><th>SOURCE</th><th>TELECALLER</th><th>SITE INSPECTOR</th><th>STATUS</th><th></th></tr></thead><tbody>${ls.map(l=>`<tr><td>${person(l)}</td><td>${badge(l.source)}</td><td>${badge(l.owner)}</td><td>${l.visitStatus==='Not required'?'Not required':esc(l.visitOwner)}<small>${esc(l.visitDate||'')}</small></td><td>${badge(l.status)}</td><td><button class="primary" data-assign-lead="${l.id}">${l.owner==='Unassigned'?'Assign lead':'Manage team'}</button></td></tr>`).join('')}</tbody></table>${ls.length?'':'<div class="empty">No leads match these filters.</div>'}</div></section><section class="card" style="margin-top:24px"><div class="card-head"><div><h2>Field job allocation</h2><p>Assign a worker and crew after a lead is confirmed.</p></div></div><div class="table-wrap"><table><thead><tr><th>CUSTOMER</th><th>SERVICE</th><th>WORKER / CREW</th><th>VISIT</th><th></th></tr></thead><tbody>${js.map(j=>`<tr><td>${person(j)}</td><td>${esc(j.service)}</td><td>${badge(j.worker)}<small>${esc(j.team)}</small></td><td>${esc(j.date)} · ${esc(j.time)}</td><td><button class="primary" data-job="${j.id}">${j.worker==='Unassigned'?'Assign work':'Manage assignment'}</button></td></tr>`).join('')}</tbody></table>${js.length?'':'<div class="empty">No jobs awaiting allocation.</div>'}</div></section>`}
function assignLeadDialog(id){if(!canAssign())return;const l=leads().find(l=>l.id===id);if(!l)return;modal(`Assign lead · ${esc(l.name)}`,`<form id="assign-lead-form" data-id="${id}"><div class="modal-body"><p>${esc(l.service)} · ${esc(l.area)}, ${esc(l.city)}<br>Source: <b>${esc(l.source)}</b></p><div class="form-grid"><label>Follow-up owner<select name="owner">${options(['Unassigned','Ananya','Kiran'],l.owner)}</select></label><label>Next follow-up<input name="followup" type="datetime-local" value="${esc(l.nextFollowup||'')}"></label><label>Site visit<select name="visit">${options(['Not required','Scheduled','Completed'],l.visitStatus)}</select></label><label>Inspector<select name="inspector">${options(['Ravi','Mahesh','Deepak'],l.visitOwner)}</select></label><label>Visit date<input name="date" type="date" value="${esc(l.visitDate||'')}"></label><label>Visit time<input name="time" type="time" value="${esc(l.visitTime||'09:00')}"></label><label class="full">Manager’s instructions<textarea name="instructions" maxlength="500" rows="3" placeholder="What should the assignee do next?"></textarea></label></div><h3 style="margin-top:24px">Assignment history</h3>${(l.assignmentHistory||[]).slice().reverse().map(a=>`<p class="sub">${esc(a.type)}: ${esc(a.from)} → ${esc(a.to)}<br>${esc(a.by)} · ${esc(a.at)}</p>`).join('')||'<p class="sub">No reassignments recorded.</p>'}</div><div class="modal-footer"><button type="button" data-action="close">Cancel</button><button class="primary">Save assignment</button></div></form>`)}
function applyLeadAssignment(id,v){if(!canAssign())throw Error('Only a manager can assign work');const l=leads().find(l=>l.id===id);if(!l)throw Error('Lead unavailable');if(!['Unassigned','Ananya','Kiran'].includes(v.owner)||!['Ravi','Mahesh','Deepak'].includes(v.inspector))throw Error('Choose a valid staff member');if(!['Not required','Scheduled','Completed'].includes(v.visit))throw Error('Choose a valid visit status');if(v.visit!=='Not required'&&(!v.date||!v.time))throw Error('Choose the inspection date and time');if(v.visit==='Completed'&&!l.visitNotes)throw Error('Record inspection findings in the lead before marking it completed');const oldOwner=l.owner,oldInspector=l.visitOwner;Object.assign(l,{owner:v.owner,nextFollowup:v.followup,visitStatus:v.visit,visitOwner:v.inspector,visitDate:v.date,visitTime:v.time});if(oldOwner!==l.owner)logAssignment(l,'Lead',oldOwner,l.owner);if(oldInspector!==l.visitOwner||v.visit==='Scheduled')logAssignment(l,'Inspector',oldInspector,l.visitOwner);if(v.instructions?.trim())l.followups.push({note:v.instructions.trim(),by:role,at:new Date().toLocaleString('en-IN')});return l}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.assignLead)assignLeadDialog(+b.dataset.assignLead)});
document.addEventListener('submit',e=>{if(e.target.id!=='assign-lead-form')return;e.preventDefault();try{const l=applyLeadAssignment(+e.target.dataset.id,Object.fromEntries(new FormData(e.target)));$('#dialog').close();save(`${l.name}: follow-up assigned to ${l.owner}`)}catch(err){toast(err.message)}});
document.addEventListener('change',e=>{if(e.target.id==='assignment-source'){assignmentSource=e.target.value;render()}if(e.target.id==='unassigned-only'){onlyUnassigned=e.target.checked;render()}if(e.target.id==='demo-person'){selectedPeople[role]=e.target.value;$('#dialog').close();render()}if(e.target.id==='role'){go(role==='Manager'?'assignments':role==='Site Inspector'?'visits':role==='Telecaller'?'leads':'overview')}});
const workflowRender=render;render=function(){workflowRender();const actions=$('.header-actions');let picker=$('#person-picker');if(demoPeople[role]){if(!picker){actions.insertAdjacentHTML('beforeend','<label id="person-picker" class="role-label">Staff <select id="demo-person" aria-label="Demo staff member"></select></label>');picker=$('#person-picker')}$('#demo-person').innerHTML=options(demoPeople[role],currentPerson());$('#profile-name').innerHTML=`${esc(currentPerson())}<small>${esc(role)} · Assigned work</small>`}else if(picker)picker.remove();if(role==='Manager')$('#profile-name').innerHTML='Service Manager<small>Lead & work assignment</small>'};

window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(access[role].includes(p)&&p!==page){page=p;query='';render()}});if(access[role].includes(location.hash.slice(1)))page=location.hash.slice(1);render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'navigate_crm_view',description:'Navigate to a CRM view available to the selected demo role.',inputSchema:{type:'object',properties:{view:{type:'string',enum:Object.keys(names)}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!access[role].includes(input.view))throw Error('View unavailable for this role');go(input.view);return {view:page,role}}})).catch(()=>{});}catch{}}

