function workspaceJobs(){return workspace==='All services'?jobs():jobs().filter(j=>j.service===workspace)}
function invoicePage(){const js=workspaceJobs(),total=js.reduce((sum,j)=>sum+j.amount,0),paid=js.reduce((sum,j)=>sum+j.paid,0);return pageHeading('Invoices & collections','Create tax-ready service invoices, share payment details and follow up on balances.',`<button class="primary" data-new-invoice>＋ Create invoice</button>`)+`<div class="filters"><select id="workspace-filter">${options(['All services','Deep cleaning','Pest control'],workspace)}</select></div><div class="stats">${stat('Invoiced value',money(total),'Selected service workspace','▤')}${stat('Collected',money(paid),'Recorded payments','✓')}${stat('Balance due',money(total-paid),'Payment follow-up required','◷')}${stat('Unpaid / part paid',js.filter(j=>j.paid<j.amount).length,'Invoices needing action','▣')}</div><section class="card"><div class="card-head"><div><h2>Invoice register</h2><p>Invoices are created from confirmed or completed service jobs.</p></div></div><div class="table-wrap"><table><thead><tr><th>INVOICE</th><th>CUSTOMER / SERVICE</th><th>TOTAL</th><th>COLLECTED</th><th>BALANCE</th><th>STATUS</th><th></th></tr></thead><tbody>${js.map(j=>`<tr><td><strong>INV-${j.id}</strong><small>${esc(j.date)}</small></td><td>${person(j)}<small>${esc(j.service)}</small></td><td>${money(j.amount)}</td><td>${money(j.paid)}</td><td>${money(j.amount-j.paid)}</td><td>${badge(j.paid===j.amount?'Paid':j.paid?'Part paid':'Unpaid')}</td><td><button class="primary" data-invoice="${j.id}">Open invoice</button></td></tr>`).join('')}</tbody></table></div></section><section class="card" style="margin-top:24px"><h2>Invoice workflow</h2><p class="sub">Manager confirms job → Accounts creates invoice → customer receives invoice and UPI QR/payment link → payment is recorded → receipt is available in customer history.</p></section>`}
function amcPage(){const list=db.amcs.filter(a=>workspace==='All services'||a.service===workspace);return pageHeading('AMC & recurring services','Schedule contracted visits, track usage, manage renewal reminders and invoice each completed service.',`<button class="primary" data-new-amc>＋ Add AMC</button>`)+`<div class="filters"><select id="workspace-filter">${options(['All services','Deep cleaning','Pest control'],workspace)}</select></div><div class="stats">${stat('Active AMCs',list.filter(a=>a.status==='Active').length,'Current service contracts','↻')}${stat('Renewal due',list.filter(a=>a.status==='Renewal due').length,'Needs follow-up','◷')}${stat('Planned visits',list.reduce((s,a)=>s+a.visits,0),'Across selected contracts','▦')}${stat('Completed visits',list.reduce((s,a)=>s+a.completed,0),'Recorded service visits','✓')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>AMC / CUSTOMER</th><th>SERVICE</th><th>TERM</th><th>VISITS</th><th>VALUE</th><th>RENEWAL</th><th>STATUS</th></tr></thead><tbody>${list.map(a=>`<tr><td><strong>${esc(a.id)}</strong><small>${esc(a.customer)}</small></td><td>${esc(a.service)}</td><td>${esc(a.start)} to ${esc(a.end)}</td><td>${a.completed} / ${a.visits}</td><td>${money(a.value)}</td><td>${esc(a.renewal)}</td><td>${badge(a.status)}</td></tr>`).join('')}</tbody></table></div></section>`}
function dispatchPage(){const js=workspaceJobs().filter(j=>j.status!=='Completed');return pageHeading('Dispatch & tracking','Monitor assigned crews, arrival time, visit duration and service status.',citySelect())+`<div class="stats">${stat('Today’s dispatches',js.length,'Scheduled and active field work','⌖')}${stat('In progress',js.filter(j=>j.status==='In progress').length,'Technicians currently on a job','◉')}${stat('Awaiting worker',js.filter(j=>!j.worker||j.worker==='Unassigned').length,'Manager action needed','⇄')}${stat('Completed today',workspaceJobs().filter(j=>j.status==='Completed').length,'With work proof and checklist','✓')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>JOB</th><th>ASSIGNED WORKER</th><th>VISIT</th><th>TRACKING</th><th>STATUS</th><th></th></tr></thead><tbody>${js.map(j=>`<tr><td>${person(j)}<small>#VC-${j.id} · ${esc(j.service)}</small></td><td>${esc(j.worker||j.team||'Unassigned')}</td><td>${esc(j.date)} · ${esc(j.time)}</td><td><small>Check-in, GPS timeline and visit timer available in field app</small></td><td>${badge(j.status)}</td><td><button class="primary" data-job="${j.id}">Open job</button></td></tr>`).join('')}</tbody></table></div></section>`}
function inventoryPage(){return pageHeading('Inventory','Track chemicals, consumables and cleaning supplies used by service teams.','<button class="primary" data-add-stock>＋ Add stock</button>')+`<section class="card"><div class="table-wrap"><table><thead><tr><th>ITEM</th><th>CATEGORY</th><th>AVAILABLE</th><th>MINIMUM</th><th>STATUS</th></tr></thead><tbody>${db.inventory.map(i=>`<tr><td><strong>${esc(i.item)}</strong></td><td>${esc(i.category)}</td><td>${i.stock} ${esc(i.unit)}</td><td>${i.minimum} ${esc(i.unit)}</td><td>${badge(i.stock<=i.minimum?'Low stock':'Available')}</td></tr>`).join('')}</tbody></table></div></section>`}
function expensePage(){const total=db.expenses.reduce((s,e)=>s+e.amount,0);return pageHeading('Expenses','Record field, material and company expenses for job profitability.',`<button class="primary" data-add-expense>＋ Add expense</button>`)+`<div class="stats">${stat('Recorded expenses',money(total),'Current demo period','₹')}${stat('Field expenses',money(db.expenses.filter(e=>e.type==='Field expense').reduce((s,e)=>s+e.amount,0)),'Technician travel and job costs','⌖')}${stat('Material costs',money(db.expenses.filter(e=>e.type==='Material').reduce((s,e)=>s+e.amount,0)),'Stock used for services','□')}${stat('Company expenses',money(db.expenses.filter(e=>e.type==='Company expense').reduce((s,e)=>s+e.amount,0)),'Operating expense','▤')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>DATE</th><th>EXPENSE</th><th>TYPE</th><th>OWNER</th><th>AMOUNT</th></tr></thead><tbody>${db.expenses.map(e=>`<tr><td>${esc(e.date)}</td><td>${esc(e.item)}</td><td>${esc(e.type)}</td><td>${esc(e.owner)}</td><td>${money(e.amount)}</td></tr>`).join('')}</tbody></table></div></section>`}
function workspacePage(){return pageHeading('Workspaces','Keep Pest Control and Deep Cleaning records, invoices and reporting separate.')+`<div class="grid">${['Pest control','Deep cleaning'].map(s=>`<section class="card"><div class="card-head"><div><p class="eyebrow">VU CARE WORKSPACE</p><h2>${s}</h2><p>${workspaceJobs().filter(j=>j.service===s).length} sample service jobs · separate service records and invoices.</p></div>${badge(workspace===s?'Current workspace':'Available')}</div><button class="primary" data-switch-workspace="${s}">Open ${s}</button></section>`).join('')}</div><section class="card" style="margin-top:24px"><h2>How workspaces are used</h2><p class="sub">The selected workspace filters invoices, AMC contracts, jobs and reports. Admin controls which users can access each service workspace.</p></section>`}
function operationalModal(kind){const map={invoice:['Create invoice',`<form id="quick-invoice"><div class="modal-body form-grid"><label>Customer<input name="customer" required></label><label>Service<select name="service">${options(['Deep cleaning','Pest control'])}</select></label><label>Invoice amount (₹)<input name="amount" type="number" min="1" required></label><label>Payment terms<select name="terms">${options(['Due on completion','Advance required','Net 7 days','Net 30 days'])}</select></label><label class="full">Notes<textarea name="notes" rows="2" placeholder="Tax, service scope or payment instructions"></textarea></label></div><div class="modal-footer"><button class="primary">Create draft invoice</button></div></form>`],amc:['Add AMC contract',`<form id="amc-form"><div class="modal-body form-grid"><label>Customer<input name="customer" required></label><label>Service<select name="service">${options(['Pest control','Deep cleaning'])}</select></label><label>Contract value (₹)<input name="value" type="number" min="1" required></label><label>Number of visits<input name="visits" type="number" min="1" required value="12"></label><label>Start date<input name="start" type="date" required></label><label>Expiry date<input name="end" type="date" required></label></div><div class="modal-footer"><button class="primary">Create AMC</button></div></form>`],stock:['Add inventory item',`<form id="stock-form"><div class="modal-body form-grid"><label>Item<input name="item" required></label><label>Category<select name="category">${options(['Pest Control','Deep Cleaning'])}</select></label><label>Quantity<input name="stock" type="number" min="0" required></label><label>Unit<input name="unit" required placeholder="litres, pieces, tubes"></label><label>Low-stock level<input name="minimum" type="number" min="0" required></label></div><div class="modal-footer"><button class="primary">Save inventory item</button></div></form>`],expense:['Add expense',`<form id="expense-form"><div class="modal-body form-grid"><label>Date<input name="date" type="date" required></label><label>Expense name<input name="item" required></label><label>Type<select name="type">${options(['Field expense','Material','Company expense'])}</select></label><label>Owner / technician<input name="owner" required></label><label>Amount (₹)<input name="amount" type="number" min="1" required></label></div><div class="modal-footer"><button class="primary">Save expense</button></div></form>`]};modal(map[kind][0],map[kind][1])}
const featureRender=render;
render=function(){if(!['invoices','amc','dispatch','inventory','expenses','workspaces'].includes(page))return featureRender();if(!access[role].includes(page)){page=access[role][0];return featureRender()}$('#nav').innerHTML=access[role].map(p=>`<a href="#${p}" class="${page===p?'active':''}" data-nav="${p}"><i>${names[p][0]}</i>${names[p][1]}</a>`).join('');$('#crumb').textContent=names[page][1];$('#profile-name').innerHTML=`${role==='Manager'?'Service Manager':role==='Admin'?'Ananya Kumar':currentPerson()}<small>${esc(role)} · Vu Care</small>`;$('#main').innerHTML=({invoices:invoicePage,amc:amcPage,dispatch:dispatchPage,inventory:inventoryPage,expenses:expensePage,workspaces:workspacePage})[page]()};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if('newInvoice'in d)operationalModal('invoice');if('newAmc'in d)operationalModal('amc');if('addStock'in d)operationalModal('stock');if('addExpense'in d)operationalModal('expense');if(d.switchWorkspace){workspace=d.switchWorkspace;page='overview';location.hash='overview';render();toast(`${workspace} workspace selected`)}});
document.addEventListener('change',e=>{if(e.target.id==='workspace-filter'){workspace=e.target.value;render()}});
document.addEventListener('submit',e=>{let f=e.target,v;if(!['quick-invoice','amc-form','stock-form','expense-form'].includes(f.id))return;e.preventDefault();v=Object.fromEntries(new FormData(f));if(f.id==='quick-invoice'){const id=Math.max(2400,...db.jobs.map(j=>j.id))+1;db.jobs.push({id,name:v.customer,service:v.service,property:'Service invoice draft',area:'Customer address pending',city:'Bangalore',amount:+v.amount,paid:0,status:'Scheduled',team:'Unassigned',worker:'Unassigned',date:'2026-09-24',time:'09:00',checks:[]});$('#dialog').close();save(`Draft invoice INV-${id} created for ${v.customer}`);page='invoices';return}if(f.id==='amc-form'){const id=`AMC-2026-${String(db.amcs.length+43).padStart(3,'0')}`;db.amcs.push({id,customer:v.customer,service:v.service,value:+v.value,start:v.start,end:v.end,visits:+v.visits,completed:0,status:'Active',renewal:v.end});$('#dialog').close();save(`${id} created for ${v.customer}`);page='amc';return}if(f.id==='stock-form'){db.inventory.push({item:v.item,category:v.category,stock:+v.stock,unit:v.unit,minimum:+v.minimum});$('#dialog').close();save(`${v.item} added to inventory`);page='inventory';return}db.expenses.unshift({date:v.date,item:v.item,type:v.type,owner:v.owner,amount:+v.amount});$('#dialog').close();save('Expense recorded');page='expenses'});
if(access[role].includes(location.hash.slice(1))){page=location.hash.slice(1);render()}

